export function ngramsOf(tokens: readonly string[], width: number): string[] {
	const windows: string[] = [];
	for (let i = 0; i + width <= tokens.length; i += 1) {
		windows.push(tokens.slice(i, i + width).join(" "));
	}
	return windows;
